#include <stdio.h>
#include "libexif/exif-data.h"
#include "libexif/exif-content.h"
#include "libexif/exif-entry.h"

int main(int argc, char** argv) {
    FILE *f = fopen(argv[1], "rb");
    unsigned char buf[256];
    int n = fread(buf, 1, 256, f);
    fclose(f);
    printf("passing %d bytes:", n-2);
    for (int i=2;i<n;i++) printf(" %02x", buf[i]);
    printf("\n");
    ExifData *d = exif_data_new_from_data(buf + 2, n - 2);
    if (!d) { printf("no data\n"); return 1; }
    ExifContent *c = d->ifd[EXIF_IFD_0];
    printf("IFD0 count=%u\n", c->count);
    for (unsigned i=0;i<c->count;i++) {
        ExifEntry *e = c->entries[i];
        printf("  entry %u: tag=0x%04x size=%u\n", i, e->tag, e->size);
    }
    return 0;
}
EOF
